package br.com.agenciafenixwarriors.liveai;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class SupabaseApi{private String accessToken;public JSONObject signIn(String email,String password)throws Exception{JSONObject body=new JSONObject().put("email",email).put("password",password);JSONObject out=new JSONObject(raw("POST","/auth/v1/token?grant_type=password",body.toString(),false));accessToken=out.getString("access_token");return out;}public JSONObject getMyProfile()throws Exception{JSONArray a=new JSONArray(raw("GET","/rest/v1/fp_profiles?select=user_id,full_name,bigo_id,member_type,status&limit=1",null,true));if(a.length()==0)throw new SecurityException("Usuário sem perfil Fênix autorizado.");JSONObject p=a.getJSONObject(0);if(!"ativo".equalsIgnoreCase(p.optString("status")))throw new SecurityException("Acesso Fênix inativo.");return p;}public JSONArray getFeatureFlags()throws Exception{return new JSONArray(raw("GET","/rest/v1/flai_feature_flags?select=key,label,enabled,min_member_type&enabled=eq.true",null,true));}private String raw(String method,String path,String body,boolean auth)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BuildConfig.SUPABASE_URL+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("apikey",BuildConfig.SUPABASE_KEY);c.setRequestProperty("Content-Type","application/json");if(auth&&accessToken!=null)c.setRequestProperty("Authorization","Bearer "+accessToken);if(body!=null){c.setDoOutput(true);try(OutputStream os=c.getOutputStream()){os.write(body.getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);if(code<200||code>=300)throw new IOException("HTTP "+code+": "+sb);return sb.toString();}}
